-- Hyprland Lua configuration (0.55+).
-- Legacy hyprlang files are retained as migration references for older installs.

local hl = hl

local home = os.getenv("HOME") or ""
local dotfiles = home .. "/.local/share/dotfiles"
local hypr_config = home .. "/.config/hypr"
local repo_config = dotfiles .. "/config/hypr"

local function file_exists(path)
	local file = io.open(path, "r")
	if file then
		file:close()
		return true
	end
	return false
end

-- Theme values are generated by matugen and switched through current/theme.
local theme_file = dotfiles .. "/current/theme/hyprland.lua"
if not file_exists(theme_file) then
	theme_file = dotfiles .. "/themes/main/hyprland.lua"
end
local theme = nil
local theme_file_handle = io.open(theme_file, "r")
if theme_file_handle then
	theme_file_handle:close()
	local theme_ok, loaded_theme = pcall(dofile, theme_file)
	if theme_ok then
		theme = loaded_theme
	end
end
local active_border_color = type(theme) == "table" and theme.active_border_color or "rgb(8A8A8D)"

-- Select hardware-specific environment and keybindings.
local hardware = "desktop"
local hardware_file = hypr_config .. "/hardware"
local file = io.open(hardware_file, "r")
if file then
	hardware = file:read("*l") or hardware
	file:close()
end
local is_laptop = hardware == "laptop" or file_exists(hypr_config .. "/conf/laptop-keybindings.conf")
local is_nvidia = hardware == "nvidia" or file_exists(hypr_config .. "/conf/nvidia-env.conf")
if is_laptop then
	hardware = is_nvidia and "laptop-nvidia" or "laptop"
elseif is_nvidia then
	hardware = "nvidia"
else
	hardware = "desktop"
end
local keybinding_file
if hardware == "laptop" or hardware == "laptop-nvidia" then
	keybinding_file = dotfiles .. "/default/hypr/lua/laptop-keybindings.lua"
else
	keybinding_file = dotfiles .. "/default/hypr/lua/desktop-keybindings.lua"
end

-- Environment settings formerly in env.conf / nvidia-env.conf.
local env = {
	HYPRCURSOR_THEME = "Bibata-Modern-Ice",
	HYPRCURSOR_SIZE = "24",
	XCURSOR_THEME = "Bibata-Modern-Ice",
	XCURSOR_SIZE = (hardware == "nvidia" or hardware == "desktop" or hardware == "laptop-nvidia") and "24" or "12",
	GDK_BACKEND = "wayland,x11,*",
	QT_QPA_PLATFORM = "wayland;xcb",
	QT_STYLE_OVERRIDE = "kvantum",
	SDL_VIDEODRIVER = "wayland",
	MOZ_ENABLE_WAYLAND = "1",
	ELECTRON_OZONE_PLATFORM_HINT = "wayland",
	OZONE_PLATFORM = "wayland",
	XDG_SESSION_TYPE = "wayland",
	XDG_CURRENT_DESKTOP = "Hyprland",
	XDG_SESSION_DESKTOP = "Hyprland",
}
for name, value in pairs(env) do
	hl.env(name, value)
end
if hardware == "nvidia" or hardware == "laptop-nvidia" then
	hl.env("NVD_BACKEND", "direct")
	hl.env("LIBVA_DRIVER_NAME", "nvidia")
	hl.env("__GLX_VENDOR_LIBRARY_NAME", "nvidia")
	hl.env("GBM_BACKEND", "nvidia-drm")
end

-- GDK_SCALE was configured alongside the legacy monitor rules.
hl.env("GDK_SCALE", "1")

-- Core look and feel.
hl.config({
	general = {
		gaps_in = 1.5,
		gaps_out = 2.5,
		border_size = 1,
		layout = "dwindle",
		resize_on_border = false,
	},
	decoration = {
		rounding = 0,
		rounding_power = 0,
		active_opacity = 0.95,
		inactive_opacity = 0.9,
		blur = {
			enabled = true,
			size = 4,
			passes = 3,
		},
		shadow = { enabled = true },
	},
	dwindle = { preserve_split = true },
	binds = {
		workspace_back_and_forth = true,
		allow_workspace_cycles = true,
		pass_mouse_when_bound = false,
	},
	misc = { disable_hyprland_logo = true },
	xwayland = { force_zero_scaling = true },
	ecosystem = { no_update_news = true },
	input = {
		kb_layout = "pl",
		kb_variant = "",
		kb_model = "",
		kb_options = "",
		kb_rules = "",
		follow_mouse = 1,
		sensitivity = 0,
		touchpad = { natural_scroll = false },
	},
})

-- Monitor fallback; setup-by-hardware writes detected monitor rules here.
local monitor_file = hypr_config .. "/conf/monitors.lua"
if not file_exists(monitor_file) then
	monitor_file = repo_config .. "/conf/monitors.lua"
end
if file_exists(monitor_file) then
	local ok, monitors = pcall(dofile, monitor_file)
	if ok and type(monitors) == "table" then
		for _, monitor in ipairs(monitors) do
			hl.monitor(monitor)
		end
	end
else
	-- Hyprland's default monitor fallback uses preferred mode and auto scale.
end

-- Animation values use the animation API exposed by newer Hyprland Lua builds.
if type(hl.animation) == "function" and type(hl.bezier) == "function" then
	hl.bezier({ name = "easeOut", x0 = 0.25, y0 = 1, x1 = 0.5, y1 = 1 })
	hl.bezier({ name = "easeOutQuint", x0 = 0.23, y0 = 1, x1 = 0.32, y1 = 1 })
	hl.bezier({ name = "easeInOutCubic", x0 = 0.65, y0 = 0.05, x1 = 0.36, y1 = 1 })
	hl.bezier({ name = "linear", x0 = 0, y0 = 0, x1 = 1, y1 = 1 })
	hl.bezier({ name = "almostLinear", x0 = 0.5, y0 = 0.5, x1 = 0.75, y1 = 1.0 })
	hl.bezier({ name = "quick", x0 = 0.15, y0 = 0, x1 = 0.1, y1 = 1 })

	hl.animation({ leaf = "global", enabled = true, speed = 5, bezier = "default" })
	hl.animation({ leaf = "windows", enabled = true, speed = 4.5, bezier = "easeOutQuint" })
	hl.animation({ leaf = "windowsIn", enabled = true, speed = 2.8, bezier = "easeOutQuint", style = "popin 87%" })
	hl.animation({ leaf = "windowsOut", enabled = true, speed = 1.2, bezier = "linear", style = "popin 87%" })
	hl.animation({ leaf = "fadeIn", enabled = true, speed = 1.73, bezier = "almostLinear" })
	hl.animation({ leaf = "fadeOut", enabled = true, speed = 1.46, bezier = "almostLinear" })
	hl.animation({ leaf = "border", enabled = true, speed = 3, bezier = "easeOutQuint" })
	hl.animation({ leaf = "fade", enabled = true, speed = 2.8, bezier = "quick" })
	hl.animation({ leaf = "layersIn", enabled = true, speed = 2.4, bezier = "easeOutQuint", style = "popin 87%" })
	hl.animation({ leaf = "layersOut", enabled = true, speed = 2.4, bezier = "easeOutQuint", style = "popin 87%" })
	hl.animation({ leaf = "fadeLayersIn", enabled = true, speed = 0.2, bezier = "quick" })
	hl.animation({ leaf = "fadeLayersOut", enabled = true, speed = 1.8, bezier = "easeOut" })
	hl.animation({ leaf = "workspaces", enabled = true, speed = 2, bezier = "easeOut", style = "slide" })
end

-- Rule modules should be applied before keybinds and autostart handlers.
local rules_config = hypr_config .. "/lua/rules.lua"
if not file_exists(rules_config) then
	rules_config = dotfiles .. "/default/hypr/lua/rules.lua"
end
if file_exists(rules_config) then
	local rules_ok, rules_error = pcall(dofile, rules_config)
	if not rules_ok then
		error("Failed to load Lua rules module: " .. tostring(rules_error))
	end
end

-- Keybind callbacks must dispatch through Hyprland's Lua dispatcher API;
-- invoking shell commands synchronously here would block the compositor.
local bindings_ok, bindings = pcall(dofile, keybinding_file)
if not bindings_ok then
	error("Failed to load keybindings module: " .. tostring(bindings))
end
local seen_bindings = {}
for _, binding in ipairs(bindings) do
	local key, command = binding.key, binding.command
	if not seen_bindings[key] then
		seen_bindings[key] = true
		pcall(hl.bind, key, function()
			hl.dsp.exec_cmd(command)
		end)
	end
end

-- Autostart previously provided through exec-once.
hl.on("hyprland.start", function()
	hl.dsp.exec_cmd("/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")
	hl.dsp.exec_cmd(dotfiles .. "/bin/wallpaper-restore")
end)

local custom_config = hypr_config .. "/lua/custom.lua"
local input_config = hypr_config .. "/conf/input.lua"
if not file_exists(input_config) then
	input_config = repo_config .. "/conf/input.lua"
end
if file_exists(input_config) then
	dofile(input_config)
end
if file_exists(custom_config) then
	dofile(custom_config)
end
